class Solution:
    def allCellsDistOrder(self, rows: int, cols: int, rCenter: int, cCenter: int) -> List[List[int]]:
        maxD = (rows - 1) + (cols - 1)
        buckets = [[] for _ in range(maxD + 1)]
        for r in range(rows):
            for c in range(cols):
                buckets[abs(r - rCenter) + abs(c - cCenter)].append([r, c])
        res = []
        for b in buckets:
            res.extend(b)
        return res

