class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int maxD = (rows - 1) + (cols - 1);
        List<List<int[]>> buckets = new ArrayList<>();
        for (int i = 0; i <= maxD; i++) buckets.add(new ArrayList<>());
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                buckets.get(Math.abs(r - rCenter) + Math.abs(c - cCenter)).add(new int[]{r, c});
        int[][] res = new int[rows * cols][2];
        int idx = 0;
        for (List<int[]> b : buckets)
            for (int[] cell : b)
                res[idx++] = cell;
        return res;
    }
}

